    窗口）；堆中没有可派发任务时返回 None。
    """
    if self._aging_interval_ms is not None:
        self._reheapify_locked(
            time.monotonic() if now is None else now
        )
    while self._inbound:
        _, _, _, entry = heapq.heappop(self._inbound)
        if not entry.done.is_set():
            return entry
    return None

